import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useSheetToday } from '../session/session';
import { type Person } from '../people/people';
import { useSettings } from '../roles/roles';
import { useRates } from '../rates/rates';
import { splitOf } from '../rates/split.slot';
import { overdueOf } from './overdue.slot';
import { useClaims } from './claims';

// A person's score: their settled-total divided by 100, minus 5 for each counted overdue claim, rounded half to even
// to a whole number. Worked in hundredths of the score so the rounding is exact.
export function scoreOf(settledTotal: string, overdueCount: number): string {
  const [whole, frac = '00'] = settledTotal.replace('-', '').split('.');
  const cents = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  // the score in ten-thousandths: cents / 10000 is the settled-total / 100
  const n = (settledTotal.startsWith('-') ? -cents : cents) - 50000n * BigInt(overdueCount);
  const negative = n < 0n;
  const m = negative ? -n : n;
  let q = m / 10000n;
  const r = m % 10000n;
  if (r > 5000n || (r === 5000n && q % 2n === 1n)) q += 1n;
  return `${negative && q !== 0n ? '-' : ''}${q}`;
}

// A person's band by the score thresholds: HIGH at or above the high one, MID at or above the mid one, else LOW;
// "" while either is blank.
export function bandOf(score: string, mid: string, high: string): string {
  if (mid === '' || high === '') return '';
  const n = BigInt(score);
  if (n >= BigInt(high)) return 'HIGH';
  if (n >= BigInt(mid)) return 'MID';
  return 'LOW';
}

function ScoreHeader() {
  return (
    <>
      <th>Score</th>
      <th>Band</th>
    </>
  );
}

function PersonScore({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  const all = claims.data ?? [];
  const { settled } = splitOf(person, all, rates.data, today, settings.data);
  const { count } = overdueOf(person, all, rates.data, today, settings.data);
  const score = scoreOf(settled, count);
  return (
    <>
      <td data-testid="person-score">{score}</td>
      <td data-testid="person-band">{bandOf(score, settings.data?.scoreMid ?? '', settings.data?.scoreHigh ?? '')}</td>
    </>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 16.5, Component: ScoreHeader }),
  PersonCells.fill({ order: 16.5, Component: PersonScore }),
];
    private final String overdueTotal;
    private final BigDecimal alertThreshold;

    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
            BigDecimal alertThreshold) {
        this.people = people;
        this.alertThreshold = alertThreshold;
        this.claimedTotal = claimedTotal;
        this.dueTotal = dueTotal;
        this.overdueTotal = overdueTotal;
    }

    /** Works out the sheet's figures now; a sheet not yet stored has none. */
    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades) {
        String id = sheetId.trim();
        Optional<Sheet> sheet = sheets.findById(id);
        Map<Long, Figures> people = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        if (sheet.isPresent()) {
            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
            var sheetRates = rates.findInChain(id);
            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
            for (Person person : persons.findListed(id)) {
                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
                BigDecimal claimed = mine.stream()
                        .filter(c -> c.getCorrects() == null && ClaimFigures.countsClaimed(c, person, sheet.get().getToday())).map(Claim::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                ClaimFigures figures = new ClaimFigures(sheetRates,
                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get());
                String due = figures.dueTotal(mine, sheet.get().getToday(), person);
                BigDecimal overdue = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c))
                        .map(figures::due).filter(d -> d != null)
                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
                BigDecimal settled = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && c.getStatus() == ClaimStatus.SETTLED)
                        .map(figures::due).filter(d -> d != null)
                        .reduce(BigDecimal.ZERO, BigDecimal::add);
                long overdueCount = mine.stream()
                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c)).count();
                String score = settled.movePointLeft(2).subtract(BigDecimal.valueOf(5 * overdueCount))
                        .setScale(0, RoundingMode.HALF_EVEN).toPlainString();
                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due,
                        overdue.toPlainString(), score));
                overdues.add(overdue);
                claimedTotal = claimedTotal.add(claimed);
                if (!"n/a".equals(due)) {
                    dues.add(new BigDecimal(due));
                }
            }
        }
        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), trimmedSum(dues),
                trimmedSum(overdues), sheet.map(Sheet::getAlertThreshold).orElse(null));
    }

    /** Adds up people's figures; with three or more, the single highest and the single lowest are left out. */
    private static String trimmedSum(List<BigDecimal> figures) {
        List<BigDecimal> sorted = figures.stream().sorted().toList();
        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
        return kept.stream().reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }

    /** One SCORE line per person, in list order, with the score as it stands in these figures: their counted SETTLED
     *  claims' dues divided by 100, minus 5 for each counted overdue claim, rounded half to even to a whole number. */
    public List<String> scores(String sheetId, String user) {
        String head = " sheet=" + sheetId.trim() + " by=" + user;
        List<String> lines = new ArrayList<>();
        people.values().forEach(f -> lines.add("SCORE" + head + " name=" + f.name() + " score=" + f.score()));
        return lines;
    }

    /** One SNAPSHOT line per person, in list order, with the due-total as it stands in these figures. */
    public List<String> snapshot(String sheetId, String user) {

